const m = $json;
const NL = String.fromCharCode(10);
const raw = (m.body && m.body.content) || m.bodyPreview || '';
const text = raw
  .replace(/<[/]?(br|p|div|tr|li|td)[^>]*>/gi, NL)
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&#34;|&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&amp;/g, '&');
const lines = text.split(NL).map(function (l) { return l.trim(); });
function field(label) {
  const p = label.toLowerCase() + ':';
  for (const l of lines) {
    if (l.toLowerCase().startsWith(p)) return l.slice(p.length).trim();
  }
  return '';
}
const first = field('First Name');
const last = field('Last Name');
const phone = field('Phone');
const email = field('Email');
const zip = field('Zip Code');
const lang = field('Lang');
let message = '';
const start = lines.findIndex(function (l) { return l.toLowerCase().startsWith('message:'); });
if (start >= 0) {
  const parts = [lines[start].slice('message:'.length).trim()];
  for (let i = start + 1; i < lines.length; i += 1) {
    const l = lines[i];
    if (l === '--' || l.toLowerCase().startsWith('this e-mail was sent from a contact form')) break;
    parts.push(l);
  }
  message = parts.join(NL).trim();
}
const fullName = [first, last].filter(Boolean).join(' ');
const parseOk = Boolean(fullName) && Boolean(email || phone) && Boolean(message);
return {
  json: {
    message_id: m.id,
    web_link: m.webLink || '',
    received_at: m.receivedDateTime || '',
    first_name: first,
    last_name: last,
    full_name: fullName,
    phone: phone,
    email: email,
    zip: zip,
    lang: lang,
    message: message.slice(0, 4000),
    parse_ok: parseOk,
    raw_text: text.replace(/\n{3,}/g, NL + NL).slice(0, 6000)
  }
};

